# THE RULE: marker count == 2 → mark as 1, else mark as background (4)

test_input = [[2, 2, 4, 9, 2], [9, 9, 4, 9, 2], [4, 4, 4, 4, 4], [9, 2, 4, 2, 2], [2, 2, 4, 2, 9], [4, 4, 4, 4, 4], [2, 9, 4, 2, 2], [9, 2, 4, 9, 2]]

marker = 9

# Row sections (size 2): [0-1], [3-4], [6-7]
# Col sections (size 2): [0-1], [3-4]

print("Corrected panel calculation:")
panel_marker_counts = {}
for r_sec_idx in range(3):
    r_start = r_sec_idx * 2  # 0, 2, 4
    r_end = r_start + 2  # 2, 4, 6
    for c_sec_idx in range(2):
        if c_sec_idx == 0:
            col_start = 0
        else:
            col_start = 3
        col_end = col_start + 2

        count = 0
        for r in range(r_start, r_end):
            for c in range(col_start, col_end):
                val = test_input[r][c]
                print(f"  Panel [{r_sec_idx},{c_sec_idx}] ({r},{c}): {val}")
                if val == marker:
                    count += 1
        key = (r_sec_idx, c_sec_idx)
        panel_marker_counts[key] = count
        print(f"  Panel [{r_sec_idx},{c_sec_idx}]: count={count} → output: {1 if count == 2 else 4}")

# Rebuild cleanly
print("\n\n=== FINAL TEST INPUT OUTPUT ===\n")

# Row sections: [0-1], [3-4], [6-7]
# Col sections: [0-1], [3-4]
# Total: 3 × 2 = 6 panels

output_grid = []
row_section_rows = [
    (0, 1),  # rows 0-1
    (3, 4),  # rows 3-4
    (6, 7),  # rows 6-7
]
col_section_cols = [
    (0, 1),  # cols 0-1
    (3, 4),  # cols 3-4
]

for r_sec_rows in row_section_rows:
    for c_sec_cols in col_section_cols:
        count = 0
        for r in range(r_sec_rows[0], r_sec_rows[1]+1):
            for c in range(c_sec_cols[0], c_sec_cols[1]+1):
                if test_input[r][c] == marker:
                    count += 1
        output = 1 if count == 2 else 4
        print(f"Panel {r_sec_rows} × {c_sec_cols}: count={count} → {output}")

